<template><view class="screen"><view class="heading">{{labels[kind]||'论坛服务'}}</view><view v-if="error" class="error">{{error}}<button @click="load">重试</button></view><view v-if="kind==='ai'" class="card"><textarea v-model="question" maxlength="200" placeholder="描述你想找的游戏或资源"/><button :disabled="busy" @click="ask">{{busy?'正在检索…':'开始 AI 搜索'}}</button><view v-if="data.answer" class="answer">{{data.answer}}</view><ThreadCard v-for="t in data.threads||[]" :key="t.tid" :thread="t"/></view><template v-else-if="kind==='lottery'"><view v-if="!data.prizes?.length&&!busy" class="empty">活动暂未开始</view><view v-else class="card"><view class="title">今日剩余 {{data.remaining||0}} 次</view><view v-for="p in data.prizes||[]" :key="p.id" class="item">{{p.name}}</view><view class="muted">每天按论坛设置提供参与次数；积分奖品自动到账，实物奖品联系管理员领取。</view><button :disabled="busy||!data.remaining" @click="draw">{{busy?'正在开奖…':'抽奖'}}</button></view><view class="card" v-for="h in data.history||[]" :key="h.id">{{h.prize}}</view></template><template v-else-if="kind==='gamebox'"><view class="card"><view class="title">{{data.site?.name}}</view><view>{{data.site?.description}}</view><button v-if="data.download?.url" @click="openExternal(data.download.url)">{{data.download.button||'前往下载'}}</button></view><view v-for="c in data.categories||[]" :key="c.title" class="card"><view class="title">{{c.title}}</view><view class="muted">{{c.text}}</view></view><ThreadCard v-for="t in data.threads||[]" :key="t.tid" :thread="t"/></template><template v-else-if="kind==='medals'"><view class="card" v-for="m in data||[]" :key="m.medalid" @click="uniModal(m)"><image :src="m.image" class="medal"/><view class="title">{{m.name}} {{m.owned?'· 已获得':''}}</view><view class="muted">{{m.description}}</view></view></template><template v-else-if="kind==='favorites'"><view v-for="t in data.list||[]" :key="t.tid"><ThreadCard :thread="t"/><view class="muted" @click="removeFavorite(t)">取消收藏</view></view><view v-if="!data.list?.length&&!busy" class="empty">还没有收藏帖子</view></template><view v-if="busy&&kind!=='ai'" class="empty">正在加载…</view></view></template>
<script setup>
import { ref } from 'vue'
import { onLoad,onReachBottom } from '@dcloudio/uni-app'
import { request,post,requireLogin } from '../../api/index.js'
import { openExternal } from '../../utils/openExternal.js'
import ThreadCard from '../../components/ThreadCard.vue'
const kind=ref(''),data=ref({}),busy=ref(false),error=ref(''),question=ref(''),labels={ai:'AI 搜索',lottery:'每日抽奖',gamebox:'游戏盒子',medals:'我的勋章',favorites:'云端收藏'}
let page=1,more=false;onReachBottom(()=>{if(kind.value==='favorites'&&more&&!busy.value)load(true)});
const paths={lottery:'lottery/draw.php',gamebox:'gamebox/list.php',medals:'user/medals.php',favorites:'thread/favorite.php'}
async function load(append=false){if(!append)page=1;if(kind.value==='ai')return;busy.value=true;error.value='';try{const d=await request(paths[kind.value],{page});if(append)data.value.list.push(...d.list);else data.value=d;if(kind.value==='favorites'){more=page<d.page.total_page;page++}}catch(e){error.value=e.message}finally{busy.value=false}}
function uniModal(m){uni.showModal({title:m.name,content:(m.owned?'已获得。':'尚未获得。')+m.description,showCancel:false})}
async function removeFavorite(t){try{await post('thread/favorite.php',{tid:t.tid,action:'remove'});data.value.list=data.value.list.filter(x=>x.tid!==t.tid)}catch(e){error.value=e.message}}
async function ask(){if(!question.value.trim()||busy.value)return;busy.value=true;error.value='';try{data.value=await post('search/ai.php',{question:question.value})}catch(e){error.value=e.message}finally{busy.value=false}}
async function draw(){if(busy.value)return;busy.value=true;try{const result=await post('lottery/draw.php',{});uni.showModal({title:'抽奖结果',content:result.prize,showCancel:false});await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onLoad(o=>{kind.value=o.kind||'gamebox';if(kind.value==='lottery'){uni.redirectTo({url:'/pages/lottery/index'});return;}if(!labels[kind.value]){error.value='服务入口无效';return}if(['lottery','medals','favorites'].includes(kind.value)&&!requireLogin())return;load()})
</script>
<style scoped>.screen{padding:20px 16px}.heading{font-size:30px;font-weight:800;margin:18px 4px}.item{padding:14px 0;border-bottom:1px solid var(--line)}.answer{white-space:pre-wrap;line-height:1.8;margin-top:24px}.medal{width:64px;height:64px}textarea{width:100%;height:110px;margin-bottom:20px}button{margin-top:20px}</style>
